use std::collections::VecDeque;impl Solution{pub fn walls_and_gates(r:&mut Vec<Vec<i32>>){if r.is_empty(){return}let mut q=VecDeque::new();for i in 0..r.len(){for j in 0..r[0].len(){if r[i][j]==0{q.push_back((i,j));}}}let d=[(1,0),(-1,0),(0,1),(0,-1)];while let Some((x,y))=q.pop_front(){for &(a,b) in &d{let i=x as i32+a;let j=y as i32+b;if i>=0&&j>=0&&i<r.len()as i32&&j<r[0].len()as i32&&r[i as usize][j as usize]==i32::MAX{r[i as usize][j as usize]=r[x][y]+1;q.push_back((i as usize,j as usize));}}}}}
